// ---- Helper to read cookies ----
function getCookie(name) {
  const value = `; ${document.cookie}`;
  const parts = value.split(`; ${name}=`);
  if (parts.length === 2) return parts.pop().split(";").shift();
}

// ---- Helper to set cookies ----
function setCookie(name, value, days) {
  const d = new Date();
  d.setTime(d.getTime() + days * 24 * 60 * 60 * 1000);
  const expires = "expires=" + d.toUTCString();
  document.cookie = `${name}=${value}; ${expires}; path=/`;
}

function load_cartdata_callback2(response, cartcount, original_total_price) {

  $.get('/?sections=ecom-side-cart', function (response) {
    if (response['ecom-side-cart']) {
        $(".ecom-cart-quick.js-items").empty();
        $(".ecom-cart-quick.js-items").append(response['ecom-side-cart']);
        
        // calcualte tax for the products
        document.dispatchEvent(new Event("calculate-taxes"));
        
        $(".product_btn span").css("display", "none");

        //get sum of all products
        let total = 0;

        // Sum with-tax items
        document.querySelectorAll('#shopify-section-ecom-side-cart [data-component="quickCartItem"] [with-tax]')
          .forEach(el => {
            const val = parseFloat(el.getAttribute("with-tax")) || 0;
            total += val;
        });

        // Sum without-tax items (convert cents → dollars)
        document.querySelectorAll('#shopify-section-ecom-side-cart [data-component="quickCartItem"] [data-price]:not([with-tax])')
          .forEach(el => {
            const val = parseFloat(el.getAttribute("data-price")) || 0;
            total += val / 100;
        });

        const formattedPrice = theme.moneyFormat.replace('/{{\s*[^}]+\s*}}/', total.toFixed(2));
        $(".csapps-cart-original-total span").text(formattedPrice).attr("data-cart-total", total);
        
        return;
    } 
  });
  
}

// engraving
//variant change then price change
try {
  const variantElements = [...document.querySelectorAll(`.product-form__option.js-enabled  span`)]
  const productID = document.querySelector(`[name="product_id"]`).value;
  const variantData = JSON.parse(document.querySelector(`#variant_data_${productID}`).innerText)
  console.log(variantData)

  for (let variantElem of variantElements) {
    const elemVariantOption = variantElem.innerText.trim();

    for (let variant of variantData.variants) {
      if (variant.option_value == elemVariantOption) {
        const variance = variant.compare_at_price - variant.price;
        let saving = (variance * 100) / variant.compare_at_price;
        saving = Math.round(saving);
        console.log(variant)

        if (isFinite(saving) == false) {
          document.querySelector(`div[data-variant-option="${variant.option_value}"]`).style.display = "none";
        } else {

          document.querySelector(`div[data-variant-option="${variant.option_value}"]`).innerText = "Save " + saving + "%"
        }
      }
    }
  }

} catch (e) {
  console.log('error in variant prices', e)
}

function showVariantData(optionValue, engraving = false) {
  const variantElements = [...document.querySelectorAll(`.product-form__option.js-enabled span`)]
  const productID = document.querySelector(`[name="product_id"]`).value;
  const variantData = JSON.parse(document.querySelector(`#variant_data_${productID}`).innerText)

  const quantity = document.getElementById("Quantity-product--static").valueAsNumber || 1;

  for (let variant of variantData.variants) {
    if (variant.option_value == optionValue) {

      console.log("selected variant", variant);
      const previewImageId = variant?.allData?.featured_media?.id;
      console.log(previewImageId)
      $(`[data-img-id="${previewImageId}"]`).click();

      document.querySelector(`.product__header .product__price [data-compare-price]`).innerText = "US$ " + (quantity * (variant.compare_at_price / 100)).toFixed(2);
      document.querySelector(`.product__header .product__price [data-product-price]`).innerText = "US$ " + (quantity * (variant.price / 100)).toFixed(2);
      document.querySelector(`.product__price .product-price-m[data-product-price]`).dataset.price = ((variant.price));
      document.querySelector(`.product__price .product-price-m[data-product-price]`).innerText = "US$ " + (quantity * (variant.price / 100)).toFixed(2);

      //if this is engraving then hide and show engraving add to cart button
      if (engraving) {

        console.log(engraving)
        const engravingBtn = document.querySelector(".engraving_add_to_cart");
        if (!engravingBtn) {
          return;
        }

        //check value is without engraving
        console.log(variant)

        if (variant.allData.option1 != "Without Engraving") {
          document.querySelector(`form[action="/cart/add"] [type="submit"] `).style.display = "";
          document.querySelector(`form[action="/cart/add"] .engraving_add_to_cart`).style.display = "none";

          document.querySelector(`.ecom_engraving`).style.display = "";
          return;
        }

        //if there is option for without engraving hide the default add to cart and show ecom add to cart
        if (variant.allData.option1 == "Without Engraving") {

          document.querySelector(`form[action="/cart/add"] [type="submit"] `).style.display = "none";
          document.querySelector(`form[action="/cart/add"] .engraving_add_to_cart`).style.display = "";
          document.querySelector(`.ecom_engraving`).style.display = "none";
        }

      }
    }
  }
}
