function setupFloatingSubmitButton() {
  const formSubmit = document.querySelector('[action="/cart/add"] [type="submit"]');
  const floatingSubmit = document.querySelector('.addtocart-floating-img-wrapper');
  const floatingBundleSubmit = document.querySelector('.addtocart-floating-img-wrapper button.btn-for-bundle');

  let observer = null;

  if (!formSubmit || !floatingSubmit) return; // safeguard

  function initObserver() {
    const headerHeight = document.querySelector('#shopify-section-header').clientHeight;

    observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            floatingSubmit.style.display = 'none';
          } else {
            floatingSubmit.style.display = 'flex';
          }
        });
      },
      {
        root: null,
        rootMargin: `-${headerHeight}px 0px 0px 0px`,
        threshold: 0
      }
    );

    observer.observe(formSubmit);
  }

  function destroyObserver() {
    if (observer) {
      observer.disconnect();
      observer = null;
    }
  }

  function handleResize() {
    if (window.innerWidth <= 768) {
      floatingSubmit.style.display = 'none'; // start hidden
      if (!observer) initObserver();
    } else {
      destroyObserver();
      floatingSubmit.style.display = 'none'; // always hidden on desktop
    }
  }

  floatingBundleSubmit?.addEventListener("click", function(e){
    document.querySelector(`.cart_button > button[type="submit"] + button`)?.click();
  });

  // Initial check
  handleResize();

  // Listen for resize events
  window.addEventListener('resize', handleResize);
}

